create table if not exists public.krim_market_readiness_requirements (
  id bigint generated by default as identity primary key,
  requirement_code text not null unique,
  jurisdiction_code text not null default '*',
  category text not null,
  title text not null,
  description text not null,
  applies_to text[] not null default array['platform']::text[],
  mandatory boolean not null default true,
  source_reference text,
  source_title text,
  source_issuer text,
  source_url text,
  source_published_at date,
  effective_from date,
  effective_until date,
  source_review_status text not null default 'draft'
    check (source_review_status in ('draft','source_checked','legal_review_pending','legal_reviewed','retired')),
  source_checked_at timestamptz,
  next_review_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint krim_market_readiness_req_jurisdiction_chk
    check (jurisdiction_code='*' or jurisdiction_code ~ '^[A-Z0-9_-]{2,12}$'),
  constraint krim_market_readiness_req_code_chk
    check (requirement_code ~ '^[A-Z0-9][A-Z0-9_-]{2,79}$')
);

create table if not exists public.krim_market_readiness_assessments (
  id bigint generated by default as identity primary key,
  market_id bigint not null references public.krim_markets(id) on delete restrict,
  requirement_id bigint not null references public.krim_market_readiness_requirements(id) on delete restrict,
  status text not null default 'pending'
    check (status in ('pending','in_review','approved','rejected','not_applicable')),
  evidence_reference text,
  reviewer_note text,
  reviewed_by uuid,
  reviewed_at timestamptz,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (market_id, requirement_id)
);

create table if not exists public.krim_market_readiness_events (
  id bigint generated by default as identity primary key,
  assessment_id bigint not null references public.krim_market_readiness_assessments(id) on delete restrict,
  market_id bigint not null references public.krim_markets(id) on delete restrict,
  requirement_code text not null,
  actor_user_id uuid not null,
  previous_status text,
  new_status text not null,
  reason text not null,
  evidence_reference text,
  created_at timestamptz not null default now()
);

create index if not exists krim_market_readiness_assessments_market_idx on public.krim_market_readiness_assessments(market_id,status);
create index if not exists krim_market_readiness_assessments_requirement_idx on public.krim_market_readiness_assessments(requirement_id,status);
create index if not exists krim_market_readiness_events_market_created_idx on public.krim_market_readiness_events(market_id,created_at desc);

alter table public.krim_market_readiness_requirements enable row level security;
alter table public.krim_market_readiness_assessments enable row level security;
alter table public.krim_market_readiness_events enable row level security;
alter table public.krim_market_readiness_requirements force row level security;
alter table public.krim_market_readiness_assessments force row level security;
alter table public.krim_market_readiness_events force row level security;

revoke all on public.krim_market_readiness_requirements from anon, authenticated;
revoke all on public.krim_market_readiness_assessments from anon, authenticated;
revoke all on public.krim_market_readiness_events from anon, authenticated;
revoke all on sequence public.krim_market_readiness_requirements_id_seq from anon, authenticated;
revoke all on sequence public.krim_market_readiness_assessments_id_seq from anon, authenticated;
revoke all on sequence public.krim_market_readiness_events_id_seq from anon, authenticated;

insert into public.krim_market_readiness_requirements
(requirement_code,jurisdiction_code,category,title,description,applies_to,mandatory,source_review_status,metadata)
values
('GLOBAL-ENTITY-ELIGIBILITY','*','legal_structure','Entity and operating-model eligibility','Obtain a jurisdiction-specific legal opinion on the permitted entity form, marketplace classification, agency/intermediary role, local establishment and any foreign ownership or control restrictions.',array['platform','marketplace'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('GLOBAL-LICENCES-PERMITS','*','licensing','Business licences and operating permits','Identify every licence, registration, permit and local establishment requirement for KRIM and each regulated service actually performed or arranged.',array['platform','road','rail','ocean','air','warehouse','customs'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('GLOBAL-TAX-INVOICING','*','tax','Tax, invoicing and marketplace reporting','Approve the actual supply chain, principal-versus-agent position, indirect/direct tax, withholding, marketplace collection/reporting, invoicing and record-retention treatment.',array['platform','marketplace','payments'],true,'draft',jsonb_build_object('launch_gate',true,'tax_adviser_required',true)),
('GLOBAL-PAYMENTS-FX','*','payments','Payments, custody, settlement and foreign exchange','Confirm the authorised payment-provider model, funds flow, custody restrictions, settlement timing, chargebacks, refunds, cross-border payments and FX controls.',array['platform','payments','finance'],true,'draft',jsonb_build_object('launch_gate',true,'regulated_provider_required',true)),
('GLOBAL-DATA-PRIVACY','*','privacy','Privacy, data transfers and retention','Map controller/processor roles, lawful bases, notices, consent, data-subject rights, cross-border transfers, retention, deletion, breach response and vendor contracts.',array['platform','all_workspaces','ai'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('GLOBAL-SANCTIONS-EXPORT','*','trade_controls','Sanctions, export controls and restricted parties','Define applicable sanctions and export-control screening for customers, partners, beneficial owners, routes, vessels, aircraft, goods and end users; document escalation and false-positive review.',array['platform','road','rail','ocean','air','customs'],true,'draft',jsonb_build_object('launch_gate',true,'screening_provider_review_required',true)),
('GLOBAL-INSURANCE-LIABILITY','*','insurance','Insurance, cargo liability and claims','Approve contractual liability allocation, carrier/forwarder liability, cargo cover, professional and cyber cover, exclusions, claims handling and proof of insurance.',array['platform','road','rail','ocean','air','warehouse'],true,'draft',jsonb_build_object('launch_gate',true,'insurance_adviser_required',true)),
('GLOBAL-WORKFORCE-SAFETY','*','workforce','Workforce, contractor and safety obligations','Determine employee/contractor classification, wage and social obligations, driver hours and qualifications, occupational safety, training, incident reporting and local labour rules.',array['platform','road','rail','ocean','air','warehouse'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('GLOBAL-CARGO-ADMISSIBILITY','*','cargo_safety','Cargo admissibility and dangerous goods','Define prohibited/restricted goods, dangerous-goods classification, packaging, marking, declarations, mode-specific training, permits and emergency procedures.',array['road','rail','ocean','air','warehouse','customs'],true,'draft',jsonb_build_object('launch_gate',true,'mode_specific_review_required',true)),
('GLOBAL-PARTNER-CAPACITY','*','network','Verified local partner and asset coverage','Verify legal identity, beneficial ownership, licences, insurance, operating capacity, subcontracting, service areas, performance controls and enforceable agreements for every activated service.',array['road','rail','ocean','air','warehouse','customs'],true,'draft',jsonb_build_object('launch_gate',true)),
('GLOBAL-CONSUMER-FAIRNESS','*','consumer_protection','Customer disclosures and fair marketplace practices','Approve transparent pricing and ranking, seller/provider identity, complaints, cancellation/refund, dispute handling, accessibility and anti-dark-pattern controls.',array['platform','marketplace','customer'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('GLOBAL-CYBER-RESILIENCE','*','security','Cybersecurity, incident response and continuity','Approve identity and access controls, secure development, logging, vulnerability management, backup/restore, incident response, disaster recovery and third-party risk.',array['platform','all_workspaces','ai'],true,'draft',jsonb_build_object('launch_gate',true)),
('IN-ENTITY-ELIGIBILITY','IN','legal_structure','India entity-form and e-commerce eligibility opinion','Obtain written Indian counsel opinion on KRIM sole-proprietorship eligibility and the applicable e-commerce entity rules, including the actual marketplace and agency model, before enabling commercial marketplace activity.',array['platform','marketplace'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true,'risk_flag','critical')),
('IN-CARRIAGE-ROAD','IN','licensing','India road-carriage role and registration assessment','Obtain written advice on whether KRIM activities fall within common-carrier, goods-booking, contractor, agent or broker definitions and identify registration/permit obligations before road-carriage operations.',array['road','marketplace'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true,'risk_flag','critical')),
('IN-GST-ECO-TCS','IN','tax','India GST, e-commerce operator and TCS assessment','Approve GST registration, supplier invoicing, e-commerce operator treatment, section 52 TCS, section 9(5) applicability and funds-flow consequences against the final contracts and transactions.',array['platform','marketplace','payments'],true,'draft',jsonb_build_object('launch_gate',true,'tax_adviser_required',true)),
('IN-RBI-FEMA-PAYMENTS','IN','payments','India RBI, payment aggregator and FEMA funds-flow review','Obtain a written funds-flow review confirming KRIM does not perform regulated payment aggregation, custody or settlement without required authorisation; assess Razorpay role, refunds, cross-border collections and FEMA controls.',array['platform','payments','finance'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true,'risk_flag','critical')),
('IN-CONSUMER-ECOMMERCE','IN','consumer_protection','India Consumer Protection and e-commerce disclosures','Review Consumer Protection Act and E-Commerce Rules as amended, grievance handling, seller/provider disclosures, ranking and sponsored listings, pricing claims, cancellation/refund and dark-pattern controls, including changes effective 1 January 2027.',array['platform','marketplace','customer'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('IN-DPDP-IT-CERTIN','IN','privacy','India privacy, data security and incident obligations','Map DPDP Act 2023 and DPDP Rules 2025 phased commencement, continuing IT Act/SPDI requirements where applicable, CERT-In directions, breach reporting, retention and cross-border processing.',array['platform','all_workspaces','ai'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('IN-IEC-CUSTOMS','IN','customs','India IEC, customs and customs-broker boundaries','Determine IEC and customs documentation requirements for each import/export flow, product restrictions and NOCs, ICEGATE processes, and whether any activity requires a licensed customs broker.',array['ocean','air','customs','marketplace'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('IN-MOTOR-VEHICLES','IN','transport_safety','India motor vehicle, permit and driver checks','Verify applicable vehicle permits, fitness, insurance, driver licence/class, goods-carriage and state-specific transport requirements for each partner and route.',array['road'],true,'draft',jsonb_build_object('launch_gate',true)),
('IN-LABOUR-CODES','IN','workforce','India labour codes and Jharkhand implementation','Assess the four Labour Codes, applicable central and Jharkhand rules, commencement and transition provisions, contractor arrangements, wages, social security and workplace safety.',array['platform','road','warehouse'],true,'draft',jsonb_build_object('launch_gate',true,'counsel_required',true)),
('IN-DANGEROUS-GOODS','IN','cargo_safety','India dangerous goods and mode-specific cargo rules','Verify applicable road, rail, air and sea dangerous-goods rules, carrier acceptance, packaging, declarations, training, permits and prohibited cargo handling.',array['road','rail','ocean','air','warehouse','customs'],true,'draft',jsonb_build_object('launch_gate',true,'mode_specific_review_required',true))
on conflict (requirement_code) do nothing;

insert into public.krim_market_readiness_assessments(market_id,requirement_id,status)
select m.id,r.id,'pending'
from public.krim_markets m
join public.krim_countries c on c.id=m.country_id
join public.krim_market_readiness_requirements r on r.jurisdiction_code='*' or r.jurisdiction_code=c.code
on conflict (market_id,requirement_id) do nothing;

create or replace function public.krim_admin_list_market_readiness()
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare v_user uuid := auth.uid(); v_result jsonb;
begin
  if v_user is null then raise exception using errcode='28000', message='Authentication required'; end if;
  if coalesce(auth.jwt()->>'aal','aal1') <> 'aal2' then raise exception using errcode='42501', message='Multi-factor authentication required'; end if;
  if not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501', message='Platform administrator permission required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'market_id',m.id,'market_code',m.code,'market_name',m.name,'country_code',c.code,'country_name',c.name,
    'catalogue_status',m.status,'catalogue_active',m.is_active,
    'requirements',coalesce((select jsonb_agg(jsonb_build_object(
      'requirement_id',r.id,'requirement_code',r.requirement_code,'category',r.category,'title',r.title,
      'description',r.description,'applies_to',r.applies_to,'mandatory',r.mandatory,
      'source_reference',r.source_reference,'source_title',r.source_title,'source_issuer',r.source_issuer,
      'source_url',r.source_url,'source_review_status',r.source_review_status,
      'assessment_id',a.id,'assessment_status',coalesce(a.status,'pending'),
      'evidence_reference',a.evidence_reference,'reviewer_note',a.reviewer_note,'reviewed_at',a.reviewed_at,'expires_at',a.expires_at
    ) order by case when r.jurisdiction_code='*' then 0 else 1 end,r.category,r.requirement_code)
    from public.krim_market_readiness_requirements r
    left join public.krim_market_readiness_assessments a on a.requirement_id=r.id and a.market_id=m.id
    where r.jurisdiction_code='*' or r.jurisdiction_code=c.code),'[]'::jsonb)
  ) order by c.name),'[]'::jsonb) into v_result
  from public.krim_markets m join public.krim_countries c on c.id=m.country_id;
  return jsonb_build_object('markets',v_result,'generated_at',now(),
    'notice','Catalogue activation is not proof of legal approval or commercial operating readiness.');
end;
$$;

create or replace function public.krim_admin_set_market_readiness_assessment(
 p_market_id bigint,p_requirement_id bigint,p_status text,p_reason text,
 p_evidence_reference text default null,p_expires_at timestamptz default null
)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
 v_user uuid:=auth.uid(); v_market public.krim_markets%rowtype; v_country_code text;
 v_req public.krim_market_readiness_requirements%rowtype;
 v_assessment public.krim_market_readiness_assessments%rowtype; v_previous text;
begin
 if v_user is null then raise exception using errcode='28000',message='Authentication required'; end if;
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception using errcode='42501',message='Multi-factor authentication required'; end if;
 if not private.krim_has_permission(v_user,1::bigint,'admin.platform') then raise exception using errcode='42501',message='Platform administrator permission required'; end if;
 if p_market_id is null or p_requirement_id is null or p_status not in ('pending','in_review','approved','rejected','not_applicable') then
  raise exception using errcode='22023',message='Invalid market, requirement or assessment status'; end if;
 if p_reason is null or length(btrim(p_reason))<20 or length(btrim(p_reason))>2000 then
  raise exception using errcode='22023',message='Provide a review reason of 20 to 2000 characters'; end if;
 if p_status in ('approved','not_applicable') and nullif(btrim(p_evidence_reference),'') is null then
  raise exception using errcode='22023',message='An evidence reference is required for approval or not-applicable decisions'; end if;
 if p_expires_at is not null and p_expires_at<=now() then
  raise exception using errcode='22023',message='Evidence expiry must be in the future'; end if;
 select * into v_market from public.krim_markets where id=p_market_id for update;
 if not found then raise exception using errcode='P0002',message='Market not found'; end if;
 select c.code into v_country_code from public.krim_countries c where c.id=v_market.country_id;
 select * into v_req from public.krim_market_readiness_requirements where id=p_requirement_id and source_review_status<>'retired';
 if not found then raise exception using errcode='P0002',message='Readiness requirement not found'; end if;
 if v_req.jurisdiction_code not in ('*',v_country_code) then raise exception using errcode='22023',message='Requirement does not apply to this market'; end if;
 select status into v_previous from public.krim_market_readiness_assessments
  where market_id=p_market_id and requirement_id=p_requirement_id for update;
 insert into public.krim_market_readiness_assessments
  (market_id,requirement_id,status,evidence_reference,reviewer_note,reviewed_by,reviewed_at,expires_at)
 values (p_market_id,p_requirement_id,p_status,nullif(btrim(p_evidence_reference),''),btrim(p_reason),v_user,now(),p_expires_at)
 on conflict (market_id,requirement_id) do update set
  status=excluded.status,evidence_reference=excluded.evidence_reference,reviewer_note=excluded.reviewer_note,
  reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,expires_at=excluded.expires_at,updated_at=now()
 returning * into v_assessment;
 insert into public.krim_market_readiness_events
  (assessment_id,market_id,requirement_code,actor_user_id,previous_status,new_status,reason,evidence_reference)
 values (v_assessment.id,p_market_id,v_req.requirement_code,v_user,v_previous,p_status,btrim(p_reason),nullif(btrim(p_evidence_reference),''));
 insert into public.krim_audit_events
  (actor_user_id,event_type,entity_type,entity_id,source,metadata,previous_state,new_state)
 values (v_user,'market_readiness.assessment_changed','krim_market_readiness_assessments',v_assessment.id::text,
  'market_readiness_console',jsonb_build_object('market_id',p_market_id,'requirement_code',v_req.requirement_code,
  'reason',btrim(p_reason),'evidence_reference',p_evidence_reference),jsonb_build_object('status',v_previous),
  jsonb_build_object('status',p_status,'reviewed_at',v_assessment.reviewed_at));
 return jsonb_build_object('success',true,'assessment_id',v_assessment.id,'market_id',p_market_id,
  'requirement_code',v_req.requirement_code,'status',p_status,'reviewed_at',v_assessment.reviewed_at);
end;
$$;

revoke all on function public.krim_admin_list_market_readiness() from public,anon;
revoke all on function public.krim_admin_set_market_readiness_assessment(bigint,bigint,text,text,text,timestamptz) from public,anon;
grant execute on function public.krim_admin_list_market_readiness() to authenticated;
grant execute on function public.krim_admin_set_market_readiness_assessment(bigint,bigint,text,text,text,timestamptz) to authenticated;

comment on table public.krim_market_readiness_requirements is 'Versioned global and jurisdiction-specific readiness register. Draft entries are not legal advice or approvals.';
comment on table public.krim_market_readiness_assessments is 'Admin-reviewed evidence status per market and requirement. Does not itself activate a market.';
comment on table public.krim_market_readiness_events is 'Append-only audit trail for market readiness assessment changes.';
